<?php require __DIR__.'/config/bootstrap.php'; $id=(int)($_GET['id']??0);$q=db()->prepare('SELECT id,grand_total,order_status,payment_method FROM orders WHERE id=?');$q->execute([$id]);$o=$q->fetch();if(!$o)exit('Order not found');?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/assets/css/store.css"></head><body><main class="panel"><h1>Order received</h1><p>Order #<?= (int)$o['id']?> · <?=money($o['grand_total'])?></p><p>Status: <?=e($o['order_status'])?> · Payment: <?=e($o['payment_method'])?></p><p>Payment remains pending until verified by staff.</p><a href="/">Back to store</a></main></body></html>